var uniquePriorityItems = []edakit.Item{
	{KP: 1, Q: "What does unique case assert at run time?",
		A: "Exactly one item matches the selector (or a default handles the rest), with no overlap between items", D: []string{"Items are evaluated in parallel hardware", "The selector has no x bits", "At most one case statement exists per module"},
		Why: "unique checks for overlapping matches and for no match (without default) and reports a violation in simulation."},
	{KP: 1, Q: "A unique case has items 2'b1? and 2'b?1 in casez. The selector is 2'b11. What does a simulator do?",
		A: "Reports a uniqueness violation, because two items match", D: []string{"Takes both branches", "Takes neither branch", "Silently takes the second item"},
		Why: "Overlap breaks the unique promise; the first match still executes but a violation is reported."},
	{KP: 1, Q: "Why can synthesis build a cheaper circuit for a unique case?",
		A: "It may assume the items are mutually exclusive and build a parallel mux instead of a priority chain", D: []string{"It may skip the selector", "It may remove all registers", "It may use fewer inputs"},
		Why: "Mutual exclusivity lets synthesis OR the selected values together rather than nest priority logic."},
	{KP: 1, Q: "What is the difference between unique and unique0?",
		A: "unique0 allows no item to match, while unique reports an error when nothing matches", D: []string{"unique0 allows overlap", "unique0 is two-state only", "There is no difference"},
		Why: "unique0 keeps the no-overlap check but drops the requirement that some item matches."},
	{KP: 2, Q: "What does priority case assert?",
		A: "At least one item matches; overlaps are allowed and the first match wins", D: []string{"Exactly one item matches", "Items are mutually exclusive", "The selector is a constant"},
		Why: "priority keeps the order-dependent semantics but promises completeness."},
	{KP: 2, Q: "A priority case with no default sees a selector that matches no item. What does a simulator do?",
		A: "Reports a violation, because priority promised that some item matches", D: []string{"Takes the first item", "Takes the last item", "Nothing at all"},
		Why: "The completeness promise is checked at run time, just as unique checks it."},
	{KP: 2, Q: "Why may synthesis avoid a latch for a priority case without a default?",
		A: "The promise that some item always matches lets it treat unlisted values as unreachable", D: []string{"Because priority adds a default automatically in simulation", "Because priority forbids latches syntactically", "Because priority case is only for clocked blocks"},
		Why: "Completeness is exactly what a latch would otherwise be inferred to cover."},
	{KP: 2, Q: "Which keyword expresses an if/else-if chain whose conditions are promised to be mutually exclusive?",
		A: "unique if", D: []string{"priority if", "parallel if", "full if"},
		Why: "unique and priority also apply to if chains, with the same meanings as for case."},
	{KP: 3, Q: "Why are unique and priority preferred over the full_case and parallel_case pragmas?",
		A: "Simulation checks the promise, so a broken assumption shows up as a violation instead of a silent mismatch", D: []string{"They are faster to type", "They change the hardware to remove muxes", "Pragmas are not allowed in SystemVerilog"},
		Why: "Pragmas only inform synthesis; the keywords make both tools act on the same assumption and check it."},
	{KP: 3, Q: "A design passes simulation with no unique violations, then fails in silicon on an input sequence never simulated. What does this show?",
		A: "Run-time checks only cover the stimulus applied; formal tools are needed to prove the promise for all inputs", D: []string{"unique does not affect synthesis", "Silicon ignores RTL", "The simulator is wrong"},
		Why: "A run-time assertion is as good as the vectors that exercise it."},
	{KP: 3, Q: "A one-hot state register drives a unique case on state. What is unique telling synthesis?",
		A: "That only one state bit pattern can match at a time, so a parallel decode is safe", D: []string{"That the state register can be removed", "That the state is binary-encoded", "That the case is clocked"},
		Why: "One-hot decodes are naturally mutually exclusive, and unique lets synthesis exploit that."},
	{KP: 3, Q: "A unique case contains a default item. What does the default change?",
		A: "The no-match check is satisfied by the default, but overlapping explicit items are still violations", D: []string{"The overlap check is disabled", "The default is never taken", "unique becomes priority"},
		Why: "A default removes the completeness concern; mutual exclusivity of the listed items is still asserted."},
}

